\textcolor{primaryblue}{\textbf{Problem:}} Find the value(s) of $c$ that satisfy the MVT for $f(x) = x^2 - 3x - 1$ on $\left[-\dfrac{1}{7}, \dfrac{13}{7}\right]$.

(From 2024 past paper, Q5 part a)

\vspace{0.3cm}
\textcolor{primaryblue}{\textbf{Solution:}}

\textbf{Step 1:} Verify MVT conditions

$f(x) = x^2 - 3x - 1$ is a polynomial, so:
\begin{itemize}
    \item Continuous on $\left[-\frac{1}{7}, \frac{13}{7}\right]$ \textcolor{green}{\checkmark}
    \item Differentiable on $\left(-\frac{1}{7}, \frac{13}{7}\right)$ \textcolor{green}{\checkmark}
\end{itemize}

MVT applies!

\textbf{Step 2:} Compute $f(a)$ and $f(b)$

Let $a = -\dfrac{1}{7}$ and $b = \dfrac{13}{7}$:

\begin{align*}
f\left(-\frac{1}{7}\right) &= \left(-\frac{1}{7}\right)^2 - 3\left(-\frac{1}{7}\right) - 1 \\
&= \frac{1}{49} + \frac{3}{7} - 1 \\
&= \frac{1 + 21 - 49}{49} \\
&= -\frac{27}{49}
\end{align*}

\begin{align*}
f\left(\frac{13}{7}\right) &= \left(\frac{13}{7}\right)^2 - 3\left(\frac{13}{7}\right) - 1 \\
&= \frac{169}{49} - \frac{39}{7} - 1 \\
&= \frac{169 - 273 - 49}{49} \\
&= -\frac{153}{49}
\end{align*}

\textbf{Step 3:} Compute average rate of change

\begin{align*}
\frac{f(b) - f(a)}{b - a} &= \frac{-\frac{153}{49} - \left(-\frac{27}{49}\right)}{\frac{13}{7} - \left(-\frac{1}{7}\right)} \\
&= \frac{-\frac{126}{49}}{\frac{14}{7}} \\
&= \frac{-\frac{126}{49}}{2} \\
&= -\frac{126}{98} \\
&= -\frac{9}{7}
\end{align*}

\textbf{Step 4:} Find $c$ by solving $f'(c) = -\dfrac{9}{7}$

\begin{align*}
f'(x) &= 2x - 3 \\
f'(c) &= -\frac{9}{7} \\
2c - 3 &= -\frac{9}{7} \\
2c &= 3 - \frac{9}{7} \\
2c &= \frac{21 - 9}{7} \\
2c &= \frac{12}{7} \\
c &= \frac{6}{7}
\end{align*}

\textbf{Step 5:} Verify $c \in \left(-\dfrac{1}{7}, \dfrac{13}{7}\right)$

Since $-\dfrac{1}{7} < \dfrac{6}{7} < \dfrac{13}{7}$ \textcolor{green}{\checkmark}

\textbf{Answer:} \boxed{c = \frac{6}{7}}

\vspace{0.5cm}

\textcolor{primaryblue}{\textbf{Problem:}} Find the value(s) of $c$ satisfying the MVT for $f(x) = x^2 - 1$ on $[0, 2]$.

(From 2021 past paper, Q4 -- related)

\vspace{0.3cm}
\textcolor{primaryblue}{\textbf{Solution:}}

\textbf{Step 1:} Verify conditions

Polynomial $\implies$ continuous and differentiable everywhere \textcolor{green}{\checkmark}

\textbf{Step 2:} Compute average rate of change

\begin{align*}
\frac{f(2) - f(0)}{2 - 0} &= \frac{(4-1) - (0-1)}{2} \\
&= \frac{3 - (-1)}{2} \\
&= \frac{4}{2} \\
&= 2
\end{align*}

\textbf{Step 3:} Solve $f'(c) = 2$

\begin{align*}
f'(x) &= 2x \\
f'(c) &= 2 \\
2c &= 2 \\
c &= 1
\end{align*}

\textbf{Step 4:} Verify $c \in (0, 2)$

$c = 1$ and $0 < 1 < 2$ \textcolor{green}{\checkmark}

\textbf{Answer:} \boxed{c = 1}

\textcolor{primaryblue}{\faLightbulb\ \textbf{Interpretation:}} At $x = 1$, the tangent slope equals the secant slope between $(0, -1)$ and $(2, 3)$.

\vspace{0.5cm}

\textcolor{primaryblue}{\textbf{Problem:}} Find the value(s) of $c$ satisfying the MVT for $f(x) = \sin x$ on $[0, \pi]$.

\vspace{0.3cm}
\textcolor{primaryblue}{\textbf{Solution:}}

\textbf{Step 1:} Verify conditions

$\sin x$ is continuous and differentiable everywhere \textcolor{green}{\checkmark}

\textbf{Step 2:} Compute average rate

\begin{align*}
\frac{f(\pi) - f(0)}{\pi - 0} &= \frac{\sin\pi - \sin 0}{\pi} \\
&= \frac{0 - 0}{\pi} \\
&= 0
\end{align*}

\textbf{Step 3:} Solve $f'(c) = 0$

\begin{align*}
f'(x) &= \cos x \\
\cos c &= 0 \\
c &= \frac{\pi}{2} \quad \text{(in } (0, \pi)\text{)}
\end{align*}

\textbf{Answer:} \boxed{c = \frac{\pi}{2}}

\textcolor{green}{\textbf{Note:}} This is the same as Rolle's Theorem since $f(0) = f(\pi) = 0$!

\vspace{0.5cm}

\textcolor{primaryblue}{\textbf{Problem:}} Use the Mean Value Theorem to prove that:
\[
|\sin a - \sin b| \leq |a - b| \quad \text{for all real } a, b
\]

(From 2023 past paper, Q4 part b -- concept)

\vspace{0.3cm}
\textcolor{primaryblue}{\textbf{Solution:}}

\textbf{Step 1:} Apply MVT to $f(x) = \sin x$ on $[a, b]$ (assume $a < b$)

$f(x) = \sin x$ is continuous and differentiable everywhere, so MVT applies.

$\exists\, c \in (a, b)$ such that:
\[
f'(c) = \frac{f(b) - f(a)}{b - a}
\]

\textbf{Step 2:} Substitute

\begin{align*}
\cos c &= \frac{\sin b - \sin a}{b - a} \\
\sin b - \sin a &= \cos c \cdot (b - a)
\end{align*}

\textbf{Step 3:} Take absolute values

\begin{align*}
|\sin b - \sin a| &= |\cos c| \cdot |b - a|
\end{align*}

\textbf{Step 4:} Use $|\cos c| \leq 1$

\begin{align*}
|\sin b - \sin a| &\leq 1 \cdot |b - a| \\
&= |b - a|
\end{align*}

For $a > b$, the same argument works with roles reversed.

\textcolor{green}{\textbf{Conclusion:}}
\[
|\sin a - \sin b| \leq |a - b| \quad \text{for all } a, b \in \mathbb{R} \quad \boxed{\text{Q.E.D.}}
\]

\textcolor{primaryblue}{\faLightbulb\ \textbf{Interpretation:}} The sine function cannot change faster than the identity function! This is because $|f'(x)| = |\cos x| \leq 1$ everywhere.

\vspace{0.5cm}

The MVT has profound theoretical consequences:

\textbf{Consequence 1 (Constant Function):}

If $f'(x) = 0$ for all $x$ in an interval $(a, b)$, then $f$ is constant on $(a, b)$.

\textbf{Proof:} Let $x_1, x_2 \in (a,b)$ with $x_1 < x_2$. By MVT, $\exists\, c \in (x_1, x_2)$ with:
\[
f(x_2) - f(x_1) = f'(c)(x_2 - x_1) = 0 \cdot (x_2 - x_1) = 0
\]

So $f(x_1) = f(x_2)$ for any two points, hence $f$ is constant. \qed

\vspace{0.3cm}
\textbf{Consequence 2 (Functions with Same Derivative):}

If $f'(x) = g'(x)$ for all $x$ in $(a, b)$, then $f$ and $g$ differ by a constant on $(a, b)$.

\textbf{Proof:} Let $h(x) = f(x) - g(x)$. Then $h'(x) = f'(x) - g'(x) = 0$ for all $x$. By Consequence 1, $h$ is constant, so $f(x) - g(x) = C$ for some constant $C$. \qed

\vspace{0.3cm}
\textbf{Consequence 3 (Increasing/Decreasing Test):}

If $f'(x) > 0$ for all $x$ in $(a, b)$, then $f$ is strictly increasing on $(a, b)$.

If $f'(x) < 0$ for all $x$ in $(a, b)$, then $f$ is strictly decreasing on $(a, b)$.

\textcolor{primaryblue}{\faInfoCircle\ \textbf{Note:}} This will be explored in detail in Section 4.4!

\vspace{0.5cm}

\textcolor{primaryblue}{\faCheckCircle\ \textbf{Section 4.3 Summary: Mean Value Theorem}}

\textbf{MVT Statement:}

Continuous on $[a,b]$ + differentiable on $(a,b)$ $\implies$ $\exists\, c \in (a,b):$
\[
\boxed{f'(c) = \frac{f(b) - f(a)}{b - a}}
\]

\textbf{Step-by-Step Application:}
\begin{enumerate}
    \item Verify both conditions (continuity and differentiability)
    \item Compute $\dfrac{f(b) - f(a)}{b-a}$
    \item Find $f'(x)$
    \item Solve $f'(c) = \dfrac{f(b) - f(a)}{b-a}$
    \item Verify $c \in (a, b)$
\end{enumerate}

\textbf{Key Facts:}
\begin{itemize}
    \item Rolle's Theorem is MVT with $f(a) = f(b)$
    \item MVT proves: $f'=0$ everywhere $\implies$ $f$ is constant
    \item MVT proves: $f' > 0$ everywhere $\implies$ $f$ is increasing
\end{itemize}

\textcolor{red}{\textbf{Exam Alert:}} MVT appears in \textbf{every past paper}! Practice finding $c$ for various function types.

\textcolor{accentorange}{\faExclamationTriangle\ \textbf{Common Mistakes:}}
\begin{itemize}
    \item Not verifying MVT conditions before applying
    \item Arithmetic errors in computing $\frac{f(b)-f(a)}{b-a}$
    \item Not checking that $c \in (a,b)$ after finding it
    \item Confusing MVT with Rolle's Theorem
\end{itemize}

\newpage

Let $f$ be defined on an interval $I$.

\textbf{Increasing:} $f$ is \textbf{increasing} on $I$ if:
\[
x_1 < x_2 \implies f(x_1) < f(x_2) \quad \text{for all } x_1, x_2 \in I
\]

\textbf{Decreasing:} $f$ is \textbf{decreasing} on $I$ if:
\[
x_1 < x_2 \implies f(x_1) > f(x_2) \quad \text{for all } x_1, x_2 \in I
\]

\textcolor{primaryblue}{\faInfoCircle\ \textbf{In Words:}}
\begin{itemize}
    \item \textbf{Increasing:} As you move left to right, the graph goes \textbf{up}
    \item \textbf{Decreasing:} As you move left to right, the graph goes \textbf{down}
\end{itemize}

\textcolor{primaryblue}{\faInfoCircle\ \textbf{Strictly vs. Non-strictly:}}
\begin{itemize}
    \item \textbf{Strictly increasing:} $x_1 < x_2 \implies f(x_1) < f(x_2)$ (no equal values)
    \item \textbf{Non-decreasing:} $x_1 < x_2 \implies f(x_1) \leq f(x_2)$ (allows flat parts)
\end{itemize}

In this course, "increasing" means "strictly increasing" unless otherwise stated.

