\textcolor{primaryblue}{\textbf{Problem:}} Find the intervals where $f(x) = x^3(4 - x)$ is increasing and decreasing.

(From 2022 past paper, Q5 part a)

\vspace{0.3cm}
\textcolor{primaryblue}{\textbf{Solution:}}

\textbf{Step 1:} Find $f'(x)$

Expand: $f(x) = 4x^3 - x^4$

\begin{align*}
f'(x) &= 12x^2 - 4x^3 \\
&= 4x^2(3 - x)
\end{align*}

\textbf{Step 2:} Find critical numbers

\[
4x^2(3 - x) = 0 \implies x = 0 \text{ or } x = 3
\]

\textbf{Step 3:} Create sign chart

Test points: $x = -1$, $x = 1$, $x = 4$

\begin{align*}
f'(-1) &= 4(1)(4) = 16 > 0 \\
f'(1) &= 4(1)(2) = 8 > 0 \\
f'(4) &= 4(16)(-1) = -64 < 0
\end{align*}

\begin{center}
\begin{tabular}{|c|c|c|c|c|c|}
\hline
\rowcolor{primaryblue!20}
& $(-\infty, 0)$ & $x = 0$ & $(0, 3)$ & $x = 3$ & $(3, \infty)$ \\
\hline
$f'(x)$ & $+$ & $0$ & $+$ & $0$ & $-$ \\
\hline
$f(x)$ & $\nearrow$ & - & $\nearrow$ & Max & $\searrow$ \\
\hline
\end{tabular}
\end{center}

\textbf{Answer:}
\begin{itemize}
    \item \textbf{Increasing:} \boxed{(-\infty, 0) \cup (0, 3) = (-\infty, 3)}
    \item \textbf{Decreasing:} \boxed{(3, \infty)}
\end{itemize}

\textcolor{primaryblue}{\faLightbulb\ \textbf{Note:}} Even though $f'(0) = 0$, the function is still increasing through $x = 0$ because $f'$ doesn't change sign there. The point $x = 0$ is an \textbf{inflection point}, not a local extremum.

