    % Panel 1: Concave Up
    \begin{scope}[shift={(0,0)}]
        \draw[->] (-0.3, 0) -- (3.5, 0) node[right] {$x$};
        \draw[->] (0, -0.3) -- (0, 2.5) node[above] {$y$};

        % Concave up curve
