        \filldraw[red] (1, 0.67) circle (1.5pt);
        \filldraw[red] (1.75, 0.5) circle (1.5pt);
        \filldraw[red] (2.5, 0.67) circle (1.5pt);

        \node[align=center] at (1.75, -0.7) {\textbf{Concave Up}\\$f'' > 0$\\Tangents below curve};
    \end{scope}

    % Panel 2: Concave Down
    \begin{scope}[shift={(5,0)}]
        \draw[->] (-0.3, 0) -- (3.5, 0) node[right] {$x$};
        \draw[->] (0, -0.3) -- (0, 2.5) node[above] {$y$};

        % Concave down curve
        \draw[primaryblue, thick, domain=0.3:3.2, samples=50] plot (\x, {-0.3*(\x-1.75)^2 + 2});

        % Tangent lines above curve
        \draw[accentorange, dashed] (0.8, 2.15) -- (1.3, 2.25);
        \draw[accentorange, dashed] (1.5, 2.02) -- (2, 1.98);
        \draw[accentorange, dashed] (2.2, 1.78) -- (2.7, 1.58);

        % Points on curve
        \filldraw[red] (1, 1.83) circle (1.5pt);
        \filldraw[red] (1.75, 2) circle (1.5pt);
        \filldraw[red] (2.5, 1.83) circle (1.5pt);

        \node[align=center] at (1.75, -0.7) {\textbf{Concave Down}\\$f'' < 0$\\Tangents above curve};
    \end{scope}
\end{tikzpicture}
\end{center}

\vspace{0.5cm}

Let $f$ be twice differentiable on an interval $I$.

\textbf{(a)} If $f''(x) > 0$ for all $x \in I$, then $f$ is \textbf{concave up} on $I$.

\textbf{(b)} If $f''(x) < 0$ for all $x \in I$, then $f$ is \textbf{concave down} on $I$.

\textcolor{primaryblue}{\faInfoCircle\ \textbf{Why This Works:}}

$f''(x) = (f')'(x)$ measures how fast $f'$ is changing.
\begin{itemize}
    \item If $f'' > 0$, then $f'$ is increasing $\to$ slopes getting steeper $\to$ concave up
    \item If $f'' < 0$, then $f'$ is decreasing $\to$ slopes getting flatter $\to$ concave down
\end{itemize}

\textcolor{primaryblue}{\faInfoCircle\ \textbf{Quick Summary:}}

\begin{center}
\begin{tabular}{|c|c|c|c|}
\hline
\rowcolor{primaryblue!20}
\textbf{Sign of $f''$} & \textbf{$f'$ is} & \textbf{Concavity} & \textbf{Shape} \\
\hline
$f'' > 0$ & Increasing & Concave Up & $\cup$ \\
\hline
$f'' < 0$ & Decreasing & Concave Down & $\cap$ \\
\hline
\end{tabular}
\end{center}

\vspace{0.5cm}

A point $(c, f(c))$ on the curve $y = f(x)$ is called an \textbf{inflection point} if:
\begin{itemize}
    \item The curve has a tangent line at $(c, f(c))$, AND
    \item The concavity changes at $x = c$
\end{itemize}

\textcolor{primaryblue}{\faInfoCircle\ \textbf{Necessary Condition:}}

If $(c, f(c))$ is an inflection point, then either:
\[
f''(c) = 0 \quad \text{OR} \quad f''(c) \text{ does not exist}
\]

\textcolor{accentorange}{\faExclamationTriangle\ \textbf{Critical Warning:}}

The converse is \textbf{FALSE}! Just because $f''(c) = 0$ doesn't mean $c$ is an inflection point.

\textbf{Example:} $f(x) = x^4$ has $f''(0) = 0$, but $x = 0$ is \textbf{not} an inflection point because concavity doesn't change (always concave up).

\textcolor{primaryblue}{\faInfoCircle\ \textbf{To Verify an Inflection Point:}}

\begin{enumerate}
    \item Find where $f''(x) = 0$ or $f''$ is undefined
    \item Check if $f''$ changes sign at that point
    \item If yes: inflection point. If no: not an inflection point.
\end{enumerate}

