\textcolor{primaryblue}{\faInfoCircle\ \textbf{Decision Guide:}}

\begin{itemize}
    \item If $f''$ is easy to compute and $f''(c) \neq 0$ $\to$ use Second Derivative Test
    \item If $f''$ is complicated or $f''(c) = 0$ $\to$ use First Derivative Test
    \item If $f''$ doesn't exist at $c$ $\to$ use First Derivative Test
\end{itemize}

\vspace{0.5cm}

\textcolor{primaryblue}{\textbf{Problem:}} Use the Second Derivative Test to find and classify all local extrema of $f(x) = x^3 - 6x^2 + 9x + 1$.

\vspace{0.3cm}
\textcolor{primaryblue}{\textbf{Solution:}}

\textbf{Step 1:} Find critical numbers

\begin{align*}
f'(x) &= 3x^2 - 12x + 9 \\
&= 3(x^2 - 4x + 3) \\
&= 3(x-1)(x-3)
\end{align*}

Setting $f'(x) = 0$:
\[
x = 1 \quad \text{or} \quad x = 3
\]

\textbf{Step 2:} Find $f''(x)$

\begin{align*}
f''(x) &= 6x - 12
\end{align*}

\textbf{Step 3:} Apply Second Derivative Test at each critical point

\textbf{At $x = 1$:}
\begin{align*}
f''(1) &= 6(1) - 12 = -6 < 0
\end{align*}

Since $f''(1) < 0$, $f$ has a \textbf{local maximum} at $x = 1$.

\textbf{At $x = 3$:}
\begin{align*}
f''(3) &= 6(3) - 12 = 6 > 0
\end{align*}

Since $f''(3) > 0$, $f$ has a \textbf{local minimum} at $x = 3$.

\textbf{Step 4:} Find function values

\begin{align*}
f(1) &= 1 - 6 + 9 + 1 = 5 \\
f(3) &= 27 - 54 + 27 + 1 = 1
\end{align*}

\textbf{Answer:}
\begin{itemize}
    \item \textbf{Local Maximum:} \boxed{f(1) = 5 \text{ at } x = 1}
    \item \textbf{Local Minimum:} \boxed{f(3) = 1 \text{ at } x = 3}
\end{itemize}

\vspace{0.5cm}

\textcolor{primaryblue}{\textbf{Problem:}} For $f(x) = 2x^3 - 3x^2 - 12x + 1$:

(a) Find all critical points

(b) Use the Second Derivative Test to classify each

(c) Find intervals of concavity

(d) Find inflection points

(From 2024 past paper, Q4 -- related)

\vspace{0.3cm}
\textcolor{primaryblue}{\textbf{Solution:}}

\textbf{(a)} Find critical points

\begin{align*}
f'(x) &= 6x^2 - 6x - 12 \\
&= 6(x^2 - x - 2) \\
&= 6(x-2)(x+1)
\end{align*}

Critical points: $x = 2$ and $x = -1$

\textbf{(b)} Second Derivative Test

Find $f''(x)$:
\begin{align*}
f''(x) &= 12x - 6
\end{align*}

\textbf{At $x = -1$:}
\begin{align*}
f''(-1) &= 12(-1) - 6 = -18 < 0
\end{align*}

$\implies$ \textbf{Local Maximum} at $x = -1$

\textbf{At $x = 2$:}
\begin{align*}
f''(2) &= 12(2) - 6 = 18 > 0
\end{align*}

$\implies$ \textbf{Local Minimum} at $x = 2$

Function values:
\begin{align*}
f(-1) &= -2 - 3 + 12 + 1 = 8 \\
f(2) &= 16 - 12 - 24 + 1 = -19
\end{align*}

\textbf{Answer (a,b):}
\begin{itemize}
    \item Local Maximum: \boxed{(-1, 8)}
    \item Local Minimum: \boxed{(2, -19)}
\end{itemize}

\textbf{(c)} Intervals of concavity

$f''(x) = 12x - 6 = 0 \implies x = \dfrac{1}{2}$

\begin{center}
\begin{tabular}{|c|c|c|}
\hline
\rowcolor{primaryblue!20}
\textbf{Interval} & \textbf{$f''(x)$} & \textbf{Concavity} \\
\hline
$\left(-\infty, \frac{1}{2}\right)$ & $-$ & Concave Down \\
\hline
$\left(\frac{1}{2}, \infty\right)$ & $+$ & Concave Up \\
\hline
\end{tabular}
\end{center}

\textbf{Answer (c):}
\begin{itemize}
    \item Concave Up: \boxed{\left(\frac{1}{2}, \infty\right)}
    \item Concave Down: \boxed{\left(-\infty, \frac{1}{2}\right)}
\end{itemize}

\textbf{(d)} Inflection point

Concavity changes at $x = \dfrac{1}{2}$:
\begin{align*}
f\left(\frac{1}{2}\right) &= 2\left(\frac{1}{8}\right) - 3\left(\frac{1}{4}\right) - 6 + 1 \\
&= \frac{1}{4} - \frac{3}{4} - 5 \\
&= -\frac{11}{2}
\end{align*}

\textbf{Answer (d):} \boxed{\text{Inflection point at } \left(\frac{1}{2}, -\frac{11}{2}\right)}

\vspace{0.5cm}

\textcolor{primaryblue}{\textbf{Problem:}} For $f(x) = x^4$:

(a) Show that $f'(0) = 0$ and $f''(0) = 0$

(b) What does the Second Derivative Test tell us?

(c) Use the First Derivative Test to determine the nature of $x = 0$

\vspace{0.3cm}
\textcolor{primaryblue}{\textbf{Solution:}}

\textbf{(a)} Compute derivatives

\begin{align*}
f'(x) &= 4x^3 \\
f''(x) &= 12x^2
\end{align*}

At $x = 0$:
\begin{align*}
f'(0) &= 0 \quad \checkmark \\
f''(0) &= 0 \quad \checkmark
\end{align*}

\textbf{(b)} Second Derivative Test result

Since $f'(0) = 0$ and $f''(0) = 0$, the Second Derivative Test is \textbf{inconclusive}.

\textbf{Answer (b):} \boxed{\text{Test fails; gives no information}}

\textbf{(c)} First Derivative Test

Check sign of $f'(x) = 4x^3$ around $x = 0$:

\begin{center}
\begin{tabular}{|c|c|c|c|}
\hline
\rowcolor{primaryblue!20}
& $(-\infty, 0)$ & $x = 0$ & $(0, \infty)$ \\
\hline
$f'(x)$ & $-$ & $0$ & $+$ \\
\hline
$f(x)$ & $\searrow$ & \textcolor{darkgreen}{\textbf{Min}} & $\nearrow$ \\
\hline
\end{tabular}
\end{center}

$f'$ changes from $-$ to $+$ at $x = 0$.

\textbf{Answer (c):} \boxed{\text{Local (and global) minimum at } x = 0}

\textcolor{primaryblue}{\faLightbulb\ \textbf{Key Lesson:}} When Second Derivative Test fails ($f''(c) = 0$), always use First Derivative Test to determine the nature of the critical point.

\vspace{0.5cm}

\textcolor{primaryblue}{\textbf{Problem:}} Use the Second Derivative Test to find and classify all local extrema of $f(x) = x + \dfrac{4}{x}$ on $(0, \infty)$.

\vspace{0.3cm}
\textcolor{primaryblue}{\textbf{Solution:}}

\textbf{Step 1:} Find critical numbers

\begin{align*}
f'(x) &= 1 - \frac{4}{x^2} = \frac{x^2 - 4}{x^2}
\end{align*}

Setting $f'(x) = 0$:
\begin{align*}
x^2 - 4 &= 0 \\
x &= 2 \quad \text{(taking positive root since domain is } (0,\infty)\text{)}
\end{align*}

\textbf{Step 2:} Find $f''(x)$

\begin{align*}
f''(x) &= \frac{d}{dx}\left(1 - \frac{4}{x^2}\right) \\
&= 0 - 4 \cdot \left(-\frac{2}{x^3}\right) \\
&= \frac{8}{x^3}
\end{align*}

\textbf{Step 3:} Apply Second Derivative Test

At $x = 2$:
\begin{align*}
f''(2) &= \frac{8}{8} = 1 > 0
\end{align*}

Since $f''(2) > 0$, $f$ has a \textbf{local minimum} at $x = 2$.

\textbf{Step 4:} Find function value

\begin{align*}
f(2) &= 2 + \frac{4}{2} = 2 + 2 = 4
\end{align*}

\textbf{Answer:} \boxed{\text{Local minimum at } (2, 4)}

\textcolor{green}{\textbf{Note:}} This is also a global minimum on $(0,\infty)$ since $f(x) \to \infty$ as $x \to 0^+$ and as $x \to \infty$.

\vspace{0.5cm}

\textcolor{primaryblue}{\faCheckCircle\ \textbf{Section 4.7 Summary: Second Derivative Test}}

\textbf{Second Derivative Test:}

If $f'(c) = 0$, then:

\begin{center}
\begin{tabular}{|c|c|}
\hline
\rowcolor{primaryblue!20}
\textbf{Sign of $f''(c)$} & \textbf{Conclusion} \\
\hline
$f''(c) > 0$ & Local Minimum at $c$ \\
\hline
$f''(c) < 0$ & Local Maximum at $c$ \\
\hline
$f''(c) = 0$ & \textcolor{red}{Test Fails} (use FDT) \\
\hline
\end{tabular}
\end{center}

\textbf{Procedure:}
\begin{enumerate}
    \item Find critical numbers: solve $f'(x) = 0$
    \item Compute $f''(x)$
    \item Evaluate $f''$ at each critical number
    \item Apply test: $f'' > 0 \to$ min, $f'' < 0 \to$ max, $f'' = 0 \to$ use FDT
    \item Find function values at extrema
\end{enumerate}

\textbf{When to Use Each Test:}
\begin{itemize}
    \item \textbf{Use Second Derivative Test:} When $f''$ is easy to compute
    \item \textbf{Use First Derivative Test:} When $f''$ is complicated or $f''(c) = 0$
\end{itemize}

\textcolor{accentorange}{\faExclamationTriangle\ \textbf{Common Mistakes:}}
\begin{itemize}
    \item Applying SDT when $f'(c) \neq 0$ (test only works at critical points!)
    \item Concluding ``no extremum'' when $f''(c) = 0$ (test is inconclusive, not negative)
    \item Not checking that $f'(c) = 0$ first
    \item Forgetting that SDT can fail
\end{itemize}

\textcolor{green}{\textbf{Memory Aid:}} ``Concave up = cup = holds minimum, Concave down = frown = maximum''

\newpage

Recall from Section 4.1:

\textbf{Absolute Maximum:} $f(c)$ is the absolute maximum if $f(c) \geq f(x)$ for all $x$ in the domain.

\textbf{Absolute Minimum:} $f(c)$ is the absolute minimum if $f(c) \leq f(x)$ for all $x$ in the domain.

\textcolor{primaryblue}{\faInfoCircle\ \textbf{Key Facts:}}
\begin{itemize}
    \item A function can have at most \textbf{one} absolute maximum value (but it may occur at multiple points)
    \item A function can have at most \textbf{one} absolute minimum value
    \item Absolute extrema can occur at:
    \begin{itemize}
        \item Critical points inside the domain
        \item Endpoints of the domain
        \item Points where the function is undefined (boundary of domain)
    \end{itemize}
\end{itemize}

\textcolor{accentorange}{\faExclamationTriangle\ \textbf{Important Distinction:}}

\textbf{Local extrema:} Highest/lowest in a neighbourhood

\textbf{Absolute extrema:} Highest/lowest over the entire domain

Every absolute extremum is a local extremum, but not every local extremum is absolute!

\vspace{0.5cm}

