\vspace{0.5cm}

\textbf{Case 1: Closed Interval $[a, b]$}

By the Extreme Value Theorem, absolute extrema \textbf{must exist}. Use the Closed Interval Method:

\begin{enumerate}
    \item Find all critical numbers in $(a, b)$
    \item Evaluate $f$ at all critical numbers
    \item Evaluate $f$ at both endpoints $a$ and $b$
    \item The largest value is the absolute maximum
    \item The smallest value is the absolute minimum
\end{enumerate}

\textbf{Case 2: Open Interval $(a, b)$ or Unbounded Interval}

Absolute extrema may \textbf{not exist}. To find them:

\begin{enumerate}
    \item Find all critical numbers
    \item Evaluate $f$ at critical numbers
    \item Check the behavior at endpoints/infinity:
    \begin{itemize}
        \item $\lim_{x \to a^+} f(x)$, $\lim_{x \to b^-} f(x)$
        \item $\lim_{x \to \pm\infty} f(x)$
    \end{itemize}
    \item Compare all values
\end{enumerate}

\textcolor{primaryblue}{\faInfoCircle\ \textbf{Key Principle:}}

Absolute extrema can only occur at:
\begin{itemize}
    \item Critical points (where $f'(x) = 0$ or $f'$ undefined)
    \item Endpoints of the domain
    \item Points approaching infinity (as limits)
\end{itemize}

\vspace{0.5cm}

\textcolor{primaryblue}{\textbf{Problem:}} Find the absolute maximum and minimum values of $f(x) = x^3 - 3x + 2$ on $[-2, 2]$.

\vspace{0.3cm}
\textcolor{primaryblue}{\textbf{Solution:}}

\textbf{Step 1:} Find critical numbers in $(-2, 2)$

\begin{align*}
f'(x) &= 3x^2 - 3 = 3(x^2 - 1) = 3(x-1)(x+1)
\end{align*}

$f'(x) = 0 \implies x = 1$ or $x = -1$

Both lie in $(-2, 2)$ \textcolor{green}{\checkmark}

\textbf{Step 2:} Evaluate at critical numbers and endpoints

\begin{align*}
f(-2) &= -8 + 6 + 2 = 0 \\
f(-1) &= -1 + 3 + 2 = 4 \\
f(1) &= 1 - 3 + 2 = 0 \\
f(2) &= 8 - 6 + 2 = 4
\end{align*}

\begin{center}
\begin{tabular}{|c|c|c|}
\hline
\rowcolor{primaryblue!20}
\textbf{$x$} & \textbf{$f(x)$} & \textbf{Type} \\
\hline
$-2$ & $0$ & Endpoint \\
\hline
$-1$ & $4$ & Critical Number \\
\hline
$1$ & $0$ & Critical Number \\
\hline
$2$ & $4$ & Endpoint \\
\hline
\end{tabular}
\end{center}

\textbf{Step 3:} Identify extrema

Largest value: $4$ (occurs at $x = -1$ and $x = 2$)

Smallest value: $0$ (occurs at $x = -2$ and $x = 1$)

\textbf{Answer:}
\begin{itemize}
    \item \textbf{Absolute Maximum:} \boxed{f(-1) = f(2) = 4}
    \item \textbf{Absolute Minimum:} \boxed{f(-2) = f(1) = 0}
\end{itemize}

\textcolor{primaryblue}{\faLightbulb\ \textbf{Note:}} The absolute maximum occurs at both a critical point ($x = -1$) and an endpoint ($x = 2$)!

\vspace{0.5cm}

\textcolor{primaryblue}{\textbf{Problem:}} Find the absolute maximum and minimum of $f(x) = x^4 - 6x^2 + 4$ on $[-3, 3]$.

(From 2025 past paper, Q1 part iii -- related)

\vspace{0.3cm}
\textcolor{primaryblue}{\textbf{Solution:}}

\textbf{Step 1:} Find critical numbers

\begin{align*}
f'(x) &= 4x^3 - 12x \\
&= 4x(x^2 - 3) \\
&= 4x(x - \sqrt{3})(x + \sqrt{3})
\end{align*}

Critical numbers: $x = 0$, $x = \sqrt{3}$, $x = -\sqrt{3}$

All lie in $(-3, 3)$ \textcolor{green}{\checkmark}

\textbf{Step 2:} Evaluate at critical numbers and endpoints

\begin{align*}
f(-3) &= 81 - 54 + 4 = 31 \\
f(-\sqrt{3}) &= 9 - 18 + 4 = -5 \\
f(0) &= 0 - 0 + 4 = 4 \\
f(\sqrt{3}) &= 9 - 18 + 4 = -5 \\
f(3) &= 81 - 54 + 4 = 31
\end{align*}

\begin{center}
\begin{tabular}{|c|c|c|}
\hline
\rowcolor{primaryblue!20}
\textbf{$x$} & \textbf{$f(x)$} & \textbf{Type} \\
\hline
$-3$ & $31$ & Endpoint \\
\hline
$-\sqrt{3}$ & $-5$ & Critical Number \\
\hline
$0$ & $4$ & Critical Number \\
\hline
$\sqrt{3}$ & $-5$ & Critical Number \\
\hline
$3$ & $31$ & Endpoint \\
\hline
\end{tabular}
\end{center}

\textbf{Answer:}
\begin{itemize}
    \item \textbf{Absolute Maximum:} \boxed{f(-3) = f(3) = 31}
    \item \textbf{Absolute Minimum:} \boxed{f(-\sqrt{3}) = f(\sqrt{3}) = -5}
\end{itemize}

\vspace{0.5cm}

\textcolor{primaryblue}{\textbf{Problem:}} Find the absolute extrema of $f(x) = \dfrac{x^2}{x^2 + 1}$ on $(-\infty, \infty)$.

\vspace{0.3cm}
\textcolor{primaryblue}{\textbf{Solution:}}

\textbf{Step 1:} Find critical numbers

\begin{align*}
f'(x) &= \frac{(x^2+1)(2x) - x^2(2x)}{(x^2+1)^2} \\
&= \frac{2x}{(x^2+1)^2}
\end{align*}

$f'(x) = 0 \implies x = 0$

\textbf{Step 2:} Evaluate at critical number

\[
f(0) = \frac{0}{1} = 0
\]

\textbf{Step 3:} Check behavior at infinity

\begin{align*}
\lim_{x \to \pm\infty} f(x) &= \lim_{x \to \pm\infty} \frac{x^2}{x^2 + 1} \\
&= \lim_{x \to \pm\infty} \frac{1}{1 + 1/x^2} \\
&= 1
\end{align*}

\textbf{Step 4:} Analyze

\begin{itemize}
    \item $f(0) = 0$ is the only critical value
    \item $f(x) \to 1$ as $x \to \pm\infty$ (but never reaches 1)
    \item Since $0 < f(x) < 1$ for all $x \neq 0$, and $f(0) = 0$
\end{itemize}

\textbf{Answer:}
\begin{itemize}
    \item \textbf{Absolute Minimum:} \boxed{f(0) = 0}
    \item \textbf{Absolute Maximum:} \boxed{\text{None (approaches 1 but never reaches it)}}
\end{itemize}

\textcolor{primaryblue}{\faLightbulb\ \textbf{Key Observation:}} On open or unbounded intervals, absolute extrema may not exist!

\vspace{0.5cm}

\textcolor{primaryblue}{\textbf{Problem:}} Find the absolute extrema of $f(x) = \sin x + \cos x$ on $[0, 2\pi]$.

\vspace{0.3cm}
\textcolor{primaryblue}{\textbf{Solution:}}

\textbf{Step 1:} Find critical numbers

\begin{align*}
f'(x) &= \cos x - \sin x
\end{align*}

$f'(x) = 0 \implies \cos x = \sin x \implies x = \dfrac{\pi}{4}, \dfrac{5\pi}{4}$

Both in $(0, 2\pi)$ \textcolor{green}{\checkmark}

\textbf{Step 2:} Evaluate at critical numbers and endpoints

\begin{align*}
f(0) &= \sin 0 + \cos 0 = 0 + 1 = 1 \\
f\left(\frac{\pi}{4}\right) &= \frac{1}{\sqrt{2}} + \frac{1}{\sqrt{2}} = \frac{2}{\sqrt{2}} = \sqrt{2} \\
f\left(\frac{5\pi}{4}\right) &= -\frac{1}{\sqrt{2}} - \frac{1}{\sqrt{2}} = -\sqrt{2} \\
f(2\pi) &= \sin 2\pi + \cos 2\pi = 0 + 1 = 1
\end{align*}

\begin{center}
\begin{tabular}{|c|c|}
\hline
\rowcolor{primaryblue!20}
\textbf{$x$} & \textbf{$f(x)$} \\
\hline
$0$ & $1$ \\
\hline
$\pi/4$ & $\sqrt{2} \approx 1.414$ \\
\hline
$5\pi/4$ & $-\sqrt{2} \approx -1.414$ \\
\hline
$2\pi$ & $1$ \\
\hline
\end{tabular}
\end{center}

\textbf{Answer:}
\begin{itemize}
    \item \textbf{Absolute Maximum:} \boxed{f\left(\frac{\pi}{4}\right) = \sqrt{2}}
    \item \textbf{Absolute Minimum:} \boxed{f\left(\frac{5\pi}{4}\right) = -\sqrt{2}}
\end{itemize}

\vspace{0.5cm}

\textcolor{primaryblue}{\textbf{Problem:}} A company's profit function is $P(x) = -x^3 + 12x^2 + 60x - 100$ (in thousands of dollars) where $x$ is the number of units produced (in thousands). Production capacity limits $x$ to $[0, 10]$. Find the production level that maximizes profit.

\vspace{0.3cm}
\textcolor{primaryblue}{\textbf{Solution:}}

\textbf{Step 1:} Find critical numbers in $(0, 10)$

\begin{align*}
P'(x) &= -3x^2 + 24x + 60 \\
&= -3(x^2 - 8x - 20) \\
&= -3(x - 10)(x + 2)
\end{align*}

$P'(x) = 0 \implies x = 10$ or $x = -2$

Only $x = 10$ is in $[0, 10]$, but it's an endpoint!

So no critical numbers in $(0, 10)$.

\textbf{Step 2:} Evaluate at endpoints

\begin{align*}
P(0) &= -100 \\
P(10) &= -1000 + 1200 + 600 - 100 = 700
\end{align*}

\textbf{Step 3:} Check if there are other critical points

Since $P'(x) = -3(x-10)(x+2)$:
\begin{itemize}
    \item For $x \in (0, 10)$: $P'(x) = -3(\text{negative})(\text{positive}) > 0$
    \item So $P$ is increasing throughout $(0, 10)$
\end{itemize}

\textbf{Answer:} Maximum profit occurs at \boxed{x = 10 \text{ thousand units}}

Maximum profit: \boxed{\$700{,}000}

\textcolor{primaryblue}{\faLightbulb\ \textbf{Business Interpretation:}} The company should produce at full capacity to maximize profit!

\vspace{0.5cm}

\textcolor{primaryblue}{\faCheckCircle\ \textbf{Section 4.8 Summary: Absolute Extrema}}

\textbf{Where Absolute Extrema Can Occur:}
\begin{enumerate}
    \item At critical points (where $f'(x) = 0$ or $f'$ undefined)
    \item At endpoints of the domain
    \item At points approaching boundaries (limits)
\end{enumerate}

\textbf{Closed Interval Method (for $[a,b]$):}
\begin{enumerate}
    \item Find all critical numbers in $(a, b)$
    \item Evaluate $f$ at: critical numbers + both endpoints
    \item Largest value = absolute max; smallest value = absolute min
\end{enumerate}

\textbf{Open/Unbounded Intervals:}
\begin{enumerate}
    \item Find critical numbers
    \item Evaluate $f$ at critical numbers
    \item Check limits at boundaries
    \item Compare all values
    \item Absolute extrema may not exist
\end{enumerate}

\textcolor{red}{\textbf{Exam Alert:}} This topic appears in \textbf{almost every past paper}! Master the Closed Interval Method.

\textcolor{accentorange}{\faExclamationTriangle\ \textbf{Most Common Mistakes:}}
\begin{itemize}
    \item \textcolor{red}{\textbf{Forgetting to evaluate at endpoints}} (most common error!)
    \item Not checking that critical numbers lie inside the interval
    \item Confusing local extrema with absolute extrema
    \item On open intervals, claiming an extremum exists when it's only approached
\end{itemize}

\textcolor{green}{\textbf{Quick Checklist:}}
\begin{itemize}
    \item[$\square$] Found all critical numbers?
    \item[$\square$] Checked they're in the interval?
    \item[$\square$] Evaluated at critical numbers?
    \item[$\square$] Evaluated at BOTH endpoints?
    \item[$\square$] Compared ALL values?
\end{itemize}

\newpage

To sketch the graph of $y = f(x)$, analyze the following features in order:

\textbf{Step 1: Domain}
\begin{itemize}
    \item Find all values of $x$ where $f(x)$ is defined
    \item Identify any excluded values (division by zero, negative under square root, etc.)
\end{itemize}

\textbf{Step 2: Intercepts}
\begin{itemize}
    \item $y$-intercept: Set $x = 0$, find $f(0)$ (if it exists)
    \item $x$-intercepts: Set $f(x) = 0$, solve for $x$
\end{itemize}

\textbf{Step 3: Symmetry}
\begin{itemize}
    \item \textbf{Even function:} $f(-x) = f(x)$ $\to$ symmetric about $y$-axis
    \item \textbf{Odd function:} $f(-x) = -f(x)$ $\to$ symmetric about origin
    \item Neither: no special symmetry
\end{itemize}

\textbf{Step 4: Asymptotes}
\begin{itemize}
    \item \textbf{Vertical:} Check $\lim_{x \to a^{\pm}} f(x) = \pm\infty$ at excluded domain points
    \item \textbf{Horizontal:} Check $\lim_{x \to \pm\infty} f(x) = L$
    \item \textbf{Oblique:} For rational functions where $\deg(p) = \deg(q) + 1$, use long division
\end{itemize}

\textbf{Step 5: Intervals of Increase and Decrease}
\begin{itemize}
    \item Find $f'(x)$
    \item Find critical numbers (where $f'(x) = 0$ or $f'$ undefined)
    \item Create sign chart for $f'$
    \item Determine where $f' > 0$ (increasing) and $f' < 0$ (decreasing)
\end{itemize}

\textbf{Step 6: Local Extrema}
\begin{itemize}
    \item Use First or Second Derivative Test
    \item Identify local maxima and minima
    \item Find coordinates of extrema
\end{itemize}

\textbf{Step 7: Concavity and Inflection Points}
\begin{itemize}
    \item Find $f''(x)$
    \item Find where $f''(x) = 0$ or $f''$ undefined
    \item Create sign chart for $f''$
    \item Determine where $f'' > 0$ (concave up) and $f'' < 0$ (concave down)
    \item Find inflection points (where concavity changes)
\end{itemize}

\textbf{Step 8: Sketch the Curve}
\begin{itemize}
    \item Plot intercepts, extrema, and inflection points
    \item Draw asymptotes as dashed lines
    \item Connect points smoothly, respecting:
    \begin{itemize}
        \item Increasing/decreasing behavior
        \item Concavity
        \item Asymptotic behavior
    \end{itemize}
\end{itemize}

