\textcolor{primaryblue}{\textbf{Problem:}} Sketch the graph of $f(x) = 2x^3 - 3x^2 - 12x + 1$ showing all key features.

(From 2025 past paper, Q4 part b)

\vspace{0.3cm}
\textcolor{primaryblue}{\textbf{Solution:}}

\textbf{Step 1: Domain}

Polynomial $\to$ domain is all real numbers: $(-\infty, \infty)$

\textbf{Step 2: Intercepts}

$y$-intercept: $f(0) = 1$ $\to$ $(0, 1)$

$x$-intercepts: Solve $2x^3 - 3x^2 - 12x + 1 = 0$ (difficult; use calculator or numerical methods)

\textbf{Step 3: Symmetry}

$f(-x) = -2x^3 - 3x^2 + 12x + 1 \neq f(x)$ and $\neq -f(x)$

No symmetry.

\textbf{Step 4: Asymptotes}

Polynomial $\to$ no asymptotes (vertical or horizontal)

As $x \to \infty$, $f(x) \to \infty$

As $x \to -\infty$, $f(x) \to -\infty$

\textbf{Step 5: Critical points and increasing/decreasing}

From previous work (Example 23):
\begin{align*}
f'(x) &= 6x^2 - 6x - 12 = 6(x-2)(x+1)
\end{align*}

Critical points: $x = -1$, $x = 2$

\begin{center}
\begin{tabular}{|c|c|c|}
\hline
\rowcolor{primaryblue!20}
\textbf{Interval} & \textbf{$f'$} & \textbf{$f$} \\
\hline
$(-\infty, -1)$ & $+$ & Increasing \\
\hline
$(-1, 2)$ & $-$ & Decreasing \\
\hline
$(2, \infty)$ & $+$ & Increasing \\
\hline
\end{tabular}
\end{center}

\textbf{Step 6: Local extrema}

Local maximum at $x = -1$: $f(-1) = 8$ $\to$ $(-1, 8)$

Local minimum at $x = 2$: $f(2) = -19$ $\to$ $(2, -19)$

\textbf{Step 7: Concavity and inflection points}

\begin{align*}
f''(x) &= 12x - 6
\end{align*}

$f''(x) = 0 \implies x = \dfrac{1}{2}$

\begin{center}
\begin{tabular}{|c|c|c|}
\hline
\rowcolor{primaryblue!20}
\textbf{Interval} & \textbf{$f''$} & \textbf{Concavity} \\
\hline
$\left(-\infty, \frac{1}{2}\right)$ & $-$ & Concave Down \\
\hline
$\left(\frac{1}{2}, \infty\right)$ & $+$ & Concave Up \\
\hline
\end{tabular}
\end{center}

Inflection point at $x = \dfrac{1}{2}$: $f\left(\dfrac{1}{2}\right) = -\dfrac{11}{2}$ $\to$ $\left(\dfrac{1}{2}, -\dfrac{11}{2}\right)$

\textbf{Step 8: Summary and sketch}

\textbf{Key Features:}
\begin{itemize}
    \item $y$-intercept: $(0, 1)$
    \item Local max: $(-1, 8)$
    \item Local min: $(2, -19)$
    \item Inflection point: $\left(\dfrac{1}{2}, -5.5\right)$
    \item End behavior: $\lim_{x \to -\infty} f(x) = -\infty$, $\lim_{x \to \infty} f(x) = \infty$
\end{itemize}

