\vspace{0.5cm}

\textcolor{primaryblue}{\textbf{Problem:}} Sketch $f(x) = \dfrac{x^2}{x^2 - 4}$ showing all asymptotes, extrema, and concavity.

(From 2022 past paper, Q6 part b)

\vspace{0.3cm}
\textcolor{primaryblue}{\textbf{Solution:}}

\textbf{Step 1: Domain}

$x^2 - 4 \neq 0 \implies x \neq \pm 2$

Domain: $(-\infty, -2) \cup (-2, 2) \cup (2, \infty)$

\textbf{Step 2: Intercepts}

$y$-intercept: $f(0) = 0$ $\to$ $(0, 0)$

$x$-intercepts: $x^2 = 0 \implies x = 0$ $\to$ $(0, 0)$

\textbf{Step 3: Symmetry}

$f(-x) = \dfrac{(-x)^2}{(-x)^2 - 4} = \dfrac{x^2}{x^2 - 4} = f(x)$

\textbf{Even function} $\to$ symmetric about $y$-axis

\textbf{Step 4: Asymptotes}

\textbf{Vertical:} At $x = 2$ and $x = -2$ (where denominator = 0)

Check limits:
\begin{align*}
\lim_{x \to 2^+} \frac{x^2}{x^2-4} &= +\infty \\
\lim_{x \to 2^-} \frac{x^2}{x^2-4} &= -\infty
\end{align*}

(Similar behavior at $x = -2$ by symmetry)

\textbf{Horizontal:} $\deg(\text{num}) = \deg(\text{den})$

\[
\lim_{x \to \pm\infty} \frac{x^2}{x^2-4} = \lim_{x \to \pm\infty} \frac{1}{1 - 4/x^2} = 1
\]

Horizontal asymptote: $y = 1$

\textbf{Step 5: Increasing/decreasing}

\begin{align*}
f'(x) &= \frac{(x^2-4)(2x) - x^2(2x)}{(x^2-4)^2} \\
&= \frac{2x^3 - 8x - 2x^3}{(x^2-4)^2} \\
&= \frac{-8x}{(x^2-4)^2}
\end{align*}

Critical number: $x = 0$

Since $(x^2-4)^2 > 0$ always, sign depends only on $-8x$:

\begin{center}
\begin{tabular}{|c|c|c|}
\hline
\rowcolor{primaryblue!20}
\textbf{Interval} & \textbf{$f'$} & \textbf{$f$} \\
\hline
$(-\infty, -2)$ & $+$ & Increasing \\
\hline
$(-2, 0)$ & $+$ & Increasing \\
\hline
$(0, 2)$ & $-$ & Decreasing \\
\hline
$(2, \infty)$ & $-$ & Decreasing \\
\hline
\end{tabular}
\end{center}

\textbf{Step 6: Local extrema}

At $x = 0$: $f'$ changes from $+$ to $-$ $\implies$ Local maximum

$f(0) = 0$ $\to$ Local max at $(0, 0)$

\textbf{Step 7: Concavity}

\begin{align*}
f''(x) &= \frac{-8(x^2-4)^2 + 8x \cdot 2(x^2-4)(2x)}{(x^2-4)^4} \\
&= \frac{-8(x^2-4) + 32x^2}{(x^2-4)^3} \\
&= \frac{24x^2 + 32}{(x^2-4)^3}
\end{align*}

Numerator $24x^2 + 32 > 0$ always, so sign depends on $(x^2-4)^3$:

\begin{center}
\begin{tabular}{|c|c|c|}
\hline
\rowcolor{primaryblue!20}
\textbf{Interval} & \textbf{$f''$} & \textbf{Concavity} \\
\hline
$|x| < 2$ & $-$ & Concave Down \\
\hline
$|x| > 2$ & $+$ & Concave Up \\
\hline
\end{tabular}
\end{center}

No inflection points (concavity changes only at discontinuities)

\textbf{Step 8: Summary}

\textbf{Key Features:}
\begin{itemize}
    \item Vertical asymptotes: $x = -2$, $x = 2$
    \item Horizontal asymptote: $y = 1$
    \item Intercept and local max: $(0, 0)$
    \item Symmetric about $y$-axis
    \item Concave down on $(-2, 2)$
    \item Concave up on $(-\infty, -2) \cup (2, \infty)$
\end{itemize}

\vspace{0.5cm}

\textcolor{primaryblue}{\faCheckCircle\ \textbf{Section 4.9 Summary: Curve Sketching}}

\textbf{8-Step Procedure:}
\begin{enumerate}
    \item Domain
    \item Intercepts
    \item Symmetry
    \item Asymptotes
    \item Increasing/Decreasing ($f'$)
    \item Local Extrema
    \item Concavity ($f''$)
    \item Sketch
\end{enumerate}

\textbf{Quick Asymptote Rules (Rational Functions):}

\begin{center}
\begin{tabular}{|c|c|}
\hline
\rowcolor{primaryblue!20}
\textbf{Condition} & \textbf{Horizontal Asymptote} \\
\hline
$\deg(p) < \deg(q)$ & $y = 0$ \\
\hline
$\deg(p) = \deg(q)$ & $y = \dfrac{\text{lead coeff of } p}{\text{lead coeff of } q}$ \\
\hline
$\deg(p) > \deg(q)$ & None (check oblique) \\
\hline
\end{tabular}
\end{center}

\textcolor{red}{\textbf{Exam Alert:}} Comprehensive curve sketching appears in most past papers. Practice the full procedure!

\textcolor{accentorange}{\faExclamationTriangle\ \textbf{Common Mistakes:}}
\begin{itemize}
    \item Not checking vertical asymptotes at excluded domain points
    \item Forgetting to verify concavity changes for inflection points
    \item Drawing curves that violate increasing/decreasing or concavity
    \item Not using symmetry when present
\end{itemize}

\textcolor{green}{\textbf{Pro Tip:}} Always check your sketch matches all the analysis:
\begin{itemize}
    \item Does it approach asymptotes correctly?
    \item Are extrema at the right locations?
    \item Does concavity match the sign of $f''$?
\end{itemize}

