\textbf{Step 1: Understand the Problem}
\begin{itemize}
    \item Read carefully and identify what is being optimized (maximized or minimized)
    \item Identify the constraints (restrictions on variables)
    \item Identify known quantities and unknowns
\end{itemize}

\textbf{Step 2: Draw a Diagram}
\begin{itemize}
    \item Sketch the physical situation whenever possible
    \item Label all relevant quantities with variables
\end{itemize}

\textbf{Step 3: Introduce Variables}
\begin{itemize}
    \item Let $x$, $y$, etc. represent unknown quantities
    \item Clearly state what each variable represents with units
\end{itemize}

\textbf{Step 4: Write the Objective Function}
\begin{itemize}
    \item Express the quantity to be optimized as a function: $Q = f(x, y, \ldots)$
    \item This is what you want to maximize or minimize
\end{itemize}

\textbf{Step 5: Use Constraints to Eliminate Variables}
\begin{itemize}
    \item Use constraint equations to express everything in terms of one variable
    \item Reduce to: $Q = g(x)$ (function of single variable)
\end{itemize}

\textbf{Step 6: Find the Domain}
\begin{itemize}
    \item Determine realistic range for the variable (physical constraints)
    \item Often $x > 0$ or $a \leq x \leq b$
\end{itemize}

\textbf{Step 7: Find Critical Points}
\begin{itemize}
    \item Compute $\dfrac{dQ}{dx}$
    \item Solve $\dfrac{dQ}{dx} = 0$
    \item Check endpoints if domain is closed interval
\end{itemize}

\textbf{Step 8: Verify Maximum or Minimum}
\begin{itemize}
    \item Use Second Derivative Test: $\dfrac{d^2Q}{dx^2}$
    \item Or use First Derivative Test (sign chart)
    \item Or compare values at critical points and endpoints
\end{itemize}

\textbf{Step 9: Answer the Question}
\begin{itemize}
    \item State the answer clearly with appropriate units
    \item Give all requested quantities (dimensions, costs, etc.)
    \item Check if answer makes physical sense
\end{itemize}

\textcolor{accentorange}{\faExclamationTriangle\ \textbf{Common Pitfalls:}}
\begin{itemize}
    \item Substituting numbers too early (before differentiating)
    \item Not stating what variables represent
    \item Finding $x$ but not answering what was actually asked
    \item Forgetting to check endpoints or domain restrictions
\end{itemize}

