\textcolor{primaryblue}{\textbf{Problem:}} A farmer has 100 meters of fencing and wants to enclose a rectangular field. What dimensions will maximize the area?

(From 2021 past paper, Q5 part b)

\vspace{0.3cm}
\textcolor{primaryblue}{\textbf{Solution:}}

\textbf{Step 1--2: Understand and draw}

Let $x$ = length and $y$ = width of rectangle (in meters)

\begin{center}
\begin{tikzpicture}[scale=0.8]
    \draw[thick] (0,0) rectangle (4,2);
    \draw[<->] (0,-0.3) -- (4,-0.3) node[midway, below] {$x$};
    \draw[<->] (-0.3,0) -- (-0.3,2) node[midway, left] {$y$};
    \node at (2,1) {Field};
\end{tikzpicture}
\end{center}

\textbf{Step 3--4: Variables and objective}

\textit{Objective:} Maximize $A = xy$

\textit{Constraint:} Perimeter = 100, so $2x + 2y = 100$

\textbf{Step 5: Eliminate one variable}

From constraint: $x + y = 50 \implies y = 50 - x$

Substitute: $A(x) = x(50 - x) = 50x - x^2$

\textbf{Step 6: Domain}

$x > 0$ and $y = 50 - x > 0 \implies 0 < x < 50$

\textbf{Step 7: Find critical points}

\begin{align*}
\frac{dA}{dx} &= 50 - 2x \\
\frac{dA}{dx} = 0 &\implies x = 25
\end{align*}

\textbf{Step 8: Verify maximum}

\[
\frac{d^2A}{dx^2} = -2 < 0 \implies \text{maximum}
\]

\textbf{Step 9: Answer}

\begin{align*}
x &= 25 \text{ m} \\
y &= 50 - 25 = 25 \text{ m} \\
A_{\max} &= 25 \times 25 = 625 \text{ m}^2
\end{align*}

\textbf{Answer:} \boxed{\text{Dimensions: } 25 \text{ m} \times 25 \text{ m (a square)}}

\textbf{Maximum area:} \boxed{625 \text{ m}^2}

\textcolor{primaryblue}{\faLightbulb\ \textbf{General Principle:}} For fixed perimeter, a square maximizes area!

\vspace{0.5cm}

\textcolor{primaryblue}{\textbf{Problem:}} A cylindrical can must hold $1000$ cm³ of liquid. Find the radius and height that minimize the total surface area (including top and bottom).

(From 2023 past paper, Q5 part b -- similar)

\vspace{0.3cm}
\textcolor{primaryblue}{\textbf{Solution:}}

\textbf{Step 1--2: Setup}

Let $r$ = radius (cm), $h$ = height (cm)

\begin{center}
\begin{tikzpicture}[scale=0.6]
    % Cylinder
    \draw[thick] (0,0) ellipse (1.5 and 0.5);
    \draw[thick] (-1.5,0) -- (-1.5,-3);
    \draw[thick] (1.5,0) -- (1.5,-3);
    \draw[thick] (0,-3) ellipse (1.5 and 0.5);

    % Labels
    \draw[<->] (0,0) -- (1.5,0) node[midway, above] {$r$};
    \draw[<->] (2,0) -- (2,-3) node[midway, right] {$h$};
\end{tikzpicture}
\end{center}

\textbf{Step 3--4: Objective and constraint}

\textit{Objective:} Minimize $S = 2\pi r^2 + 2\pi rh$ (two circles + lateral surface)

\textit{Constraint:} Volume = 1000, so $\pi r^2 h = 1000$

\textbf{Step 5: Eliminate $h$}

From constraint: $h = \dfrac{1000}{\pi r^2}$

Substitute:
\begin{align*}
S(r) &= 2\pi r^2 + 2\pi r \cdot \frac{1000}{\pi r^2} \\
&= 2\pi r^2 + \frac{2000}{r}
\end{align*}

\textbf{Step 6: Domain}

$r > 0$

\textbf{Step 7: Critical points}

\begin{align*}
\frac{dS}{dr} &= 4\pi r - \frac{2000}{r^2} \\
\frac{dS}{dr} = 0 &\implies 4\pi r = \frac{2000}{r^2} \\
4\pi r^3 &= 2000 \\
r^3 &= \frac{500}{\pi} \\
r &= \sqrt[3]{\frac{500}{\pi}} \approx 5.42 \text{ cm}
\end{align*}

\textbf{Step 8: Verify minimum}

\[
\frac{d^2S}{dr^2} = 4\pi + \frac{4000}{r^3} > 0 \text{ always} \implies \text{minimum}
\]

\textbf{Step 9: Find $h$}

\begin{align*}
h &= \frac{1000}{\pi r^2} = \frac{1000}{\pi \left(\frac{500}{\pi}\right)^{2/3}} \\
&= \frac{1000}{\pi} \cdot \left(\frac{\pi}{500}\right)^{2/3} \\
&= 2\sqrt[3]{\frac{500}{\pi}} = 2r \approx 10.84 \text{ cm}
\end{align*}

\textbf{Answer:} \boxed{r \approx 5.42 \text{ cm}, \quad h \approx 10.84 \text{ cm}}

\textcolor{primaryblue}{\faLightbulb\ \textbf{Beautiful Result:}} Optimal cylinder has $h = 2r$ (height = diameter)!

