\textcolor{primaryblue}{\textbf{Problem:}} An open box is made by cutting equal squares from each corner of a 12 cm $\times$ 12 cm piece of cardboard and folding up the sides. Find the size of the square cut that maximizes volume.

(From 2024 past paper, Q5 part b -- similar)

\vspace{0.3cm}
\textcolor{primaryblue}{\textbf{Solution:}}

\textbf{Step 1--2: Diagram}

Let $x$ = side length of cut squares (cm)

\begin{center}
\begin{tikzpicture}[scale=0.7]
    % Flat cardboard
    \draw[thick] (0,0) rectangle (4,4);

    % Cut squares
    \draw[dashed] (0,0) -- (0.6,0.6);
    \draw[dashed] (4,0) -- (3.4,0.6);
    \draw[dashed] (0,4) -- (0.6,3.4);
    \draw[dashed] (4,4) -- (3.4,3.4);

    % Labels
    \node at (0.3,0.3) {$x$};
    \node at (2,2) {12 cm};

    % Folded box
    \begin{scope}[shift={(6,0.5)}]
        \draw[thick] (0,0) -- (0,1.5) -- (3,1.5) -- (3,0);
        \draw[thick] (0,0) -- (0.5,-0.3) -- (3.5,-0.3) -- (3,0);
        \draw[thick] (3,1.5) -- (3.5,1.2) -- (3.5,-0.3);
        \draw[dashed] (0,1.5) -- (0.5,1.2) -- (3.5,1.2);
        \draw[dashed] (0.5,1.2) -- (0.5,-0.3);

        \draw[<->] (3.7,0) -- (3.7,1.5) node[midway,right] {$x$};
    \end{scope}
\end{tikzpicture}
\end{center}

\textbf{Step 3--4: Objective}

After cutting and folding:
\begin{itemize}
    \item Length = Width = $12 - 2x$
    \item Height = $x$
\end{itemize}

\textit{Objective:} Maximize $V = x(12-2x)^2$

\textbf{Step 5--6: Domain}

$x > 0$ and $12 - 2x > 0 \implies 0 < x < 6$

\textbf{Step 7: Critical points}

Expand: $V = x(144 - 48x + 4x^2) = 144x - 48x^2 + 4x^3$

\begin{align*}
\frac{dV}{dx} &= 144 - 96x + 12x^2 \\
&= 12(12 - 8x + x^2) \\
&= 12(x-2)(x-6)
\end{align*}

$\dfrac{dV}{dx} = 0 \implies x = 2$ or $x = 6$

Only $x = 2 \in (0, 6)$ is valid.

\textbf{Step 8: Verify maximum}

\[
\frac{d^2V}{dx^2} = -96 + 24x
\]

At $x = 2$: $\dfrac{d^2V}{dx^2} = -96 + 48 = -48 < 0 \implies$ maximum

\textbf{Step 9: Answer and volume}

\begin{align*}
x &= 2 \text{ cm} \\
V_{\max} &= 2(12-4)^2 = 2(64) = 128 \text{ cm}^3
\end{align*}

\textbf{Answer:} \boxed{\text{Cut squares of side } 2 \text{ cm}}

\textbf{Maximum volume:} \boxed{128 \text{ cm}^3}

Box dimensions: $8 \times 8 \times 2$ cm

