\textcolor{primaryblue}{\faCheckCircle\ \textbf{Section 4.10 Summary: Optimization}}

\textbf{9-Step Strategy:}
\begin{enumerate}
    \item Understand the problem
    \item Draw a diagram
    \item Introduce variables
    \item Write objective function
    \item Use constraints to eliminate variables
    \item Find domain
    \item Find critical points
    \item Verify max/min
    \item Answer the question (with units!)
\end{enumerate}

\textbf{Classic Results to Remember:}
\begin{itemize}
    \item Fixed perimeter $\to$ max area: \textbf{square}
    \item Fixed volume cylinder $\to$ min surface area: $h = 2r$
    \item Sum of two numbers fixed $\to$ max product: \textbf{equal numbers}
\end{itemize}

\textcolor{red}{\textbf{Exam Alert:}} Optimization appears frequently in past papers. Always show complete setup and working!

\textcolor{accentorange}{\faExclamationTriangle\ \textbf{Top Mistakes in Optimization:}}
\begin{itemize}
    \item \textcolor{red}{Not using constraint} to reduce to one variable
    \item \textcolor{red}{Substituting numbers before differentiating}
    \item \textcolor{red}{Finding $x$ but not answering} what was asked
    \item \textcolor{red}{Forgetting units} in final answer
    \item Not checking domain restrictions
    \item Not verifying whether it's a max or min
\end{itemize}

\textcolor{green}{\textbf{Success Checklist:}}
\begin{itemize}
    \item[$\square$] Drew a diagram?
    \item[$\square$] Stated what variables represent?
    \item[$\square$] Used constraint correctly?
    \item[$\square$] Verified max/min?
    \item[$\square$] Answered actual question with units?
    \item[$\square$] Does answer make physical sense?
\end{itemize}

